exports.handler = async (event, context) => {
  console.log('ESM_EVENT '+JSON.stringify({requestId:context.awsRequestId,event}));
  const parsed=event.Records.map(r=>{try{return JSON.parse(r.body)}catch{return {mode:'success',token:r.body}}});
  const first=event.Records.some(r=>Number(r.attributes.ApproximateReceiveCount)===1);
  const mode=parsed.find(p=>p.mode && p.mode!=='success')?.mode || 'success';
  if(mode==='error_once' && first){
    console.log('ESM_THROW '+JSON.stringify({requestId:context.awsRequestId,mode}));
    throw new Error('owned deliberate first-receive batch failure');
  }
  let response={batchItemFailures:[]};
  if(mode==='partial_once') response={batchItemFailures:event.Records.filter((r,i)=>parsed[i].fail && Number(r.attributes.ApproximateReceiveCount)===1).map(r=>({itemIdentifier:r.messageId}))};
  if(first){
    if(mode==='unknown_id') response={batchItemFailures:[{itemIdentifier:'00000000-0000-0000-0000-999000999000'}]};
    if(mode==='empty_id') response={batchItemFailures:[{itemIdentifier:''}]};
    if(mode==='missing_id') response={batchItemFailures:[{}]};
    if(mode==='number_id') response={batchItemFailures:[{itemIdentifier:123}]};
    if(mode==='wrong_list') response={batchItemFailures:'not-an-array'};
  }
  console.log('ESM_RESPONSE '+JSON.stringify({requestId:context.awsRequestId,response}));
  return response;
};
